"headers"]={-75,-45},["instanceID"]=1209,["localFacts"]={["coords"]={["2025"]={{52.3,39.5}}},["kind"]="Quest",["lvl"]=10,["qgs"]={205706},["questID"]=76142,["record"]=385423,["sourceQuests"]={76140}},["lvl"]=10,["maps"]={2190,2191,2192,2193,2194,2195,2196,2197,2198},["qgs"]={205706},["questID"]=76142,["sourceQuests"]={76140}},["76143"]={["awp"]=100105,["coords"]={["2025"]={{61.4,79.7}}},["expansionID"]=10,["headers"]={-75,-45},["instanceID"]=1209,["localFacts"]={["coords"]={["2025"]={{61.4,79.7}}},["kind"]="Quest",["lvl"]=10,["qgs"]={205707},["questID"]=76143,["record"]=385427,["sourceQuests"]={76141,76142}},["lvl"]=10,["maps"]={2190,2191,2192,2193,2194,2195,2196,2197,2198},["qgs"]={205707},["questID"]=76143,["sourceQuests"]={76141,76142}},["76144"]={["awp"]=100105,["coords"]={["2025"]={{61.4,79.7}}},["expansionID"]=10,["headers"]={-75,-45},["instanceID"]=1209,["localFacts"]={["coords"]={["2025"]={{61.4,79.7}}},["kind"]="Quest",["lvl"]=10,["qgs"]={205707},["questID"]=76144,["record"]=385429,["sourceQuests"]={76143}},["lvl"]=10,["maps"]={2190,2191,2192,2193,2194,2195,2196,2197,2198},["qgs"]={205707},["questID"]=76144,["sourceQuests"]={76143}},["76145"]={["awp"]=100105,["coords"]={["2025"]={{62.1,81.5}}},["expansionID"]=10,["headers"]={-75,-45},["instanceID"]=1209,["localFacts"]={["coords"]={["2025"]={{62.1,81.5}}},["kind"]="Quest",["lvl"]=10,["qgs"]={206149},["questID"]=76145,["record"]=385430,["sourceQuests"]={76144}},["lvl"]=10,["maps"]={2190,2191,2192,2193,2194,2195,2196,2197,2198},["qgs"]={206149},["questID"]=76145,["sourceQuests"]={76144}},["76146"]={["awp"]=100105,["coords"]={["2025"]={{62.2,83.2}}},["expansionID"]=10,["headers"]={-75,-45},["instanceID"]=1209,["localFacts"]={["coords"]={["2025"]={{62.2,83.2}}},["kind"]="Quest",["lvl"]=10,["qgs"]={205710},["questID"]=76146,["record"]=385431,["sourceQuests"]={76145}},["lvl"]=10,["maps"]={2190,2191,2192,2193,2194,2195,2196,2197,2198},["qgs"]={205710},["questID"]=76146,["sourceQuests"]={76145}},["76171"]={["awp"]=100107,["coords"]={["2024"]={{17.5,31.5}}},["expansionID"]=10,["headers"]={-735,-170,-45},["localFacts"]={["coords"]={["2024"]={{17.5,31.5}}},["kind"]="Quest",["lvl"]=10,["minReputation"]={2510,12},["qgs"]={206221},["questID"]=76171,["record"]=111523,["sourceQuests"]={75634}},["lvl"]=10,["minReputation"]={2510,12},["qgs"]={206221},["questID"]=76171,["sourceQuests"]={75634}},["76176"]={["awp"]=100107,["coords"]={["2025"]={{59.9,58.7}}},["expansionID"]=10,["headers"]={-735,-170,-45},["localFacts"]={["coords"]={["2025"]={{59.9,58.7}}},["kind"]="Quest",["lvl"]=10,["minReputation"]={2510,12},["qgs"]={208968},["questID"]=76176,["record"]=111532,["sourceQuests"]={75635}},["lvl"]=10,["minReputation"]={2510,12},["qgs"]={208968},["questID"]=76176,["sourceQuests"]={75635}},["76249"]={["awp"]=100105,["coords"]={["22"]={{69.07,72.96}}},["cost"]={{"i",206355,1},{"i",206354,1},{"i",206358,1},{"i",206356,1},{"i",206346,1},{"i",206364,1},{"i",206357,1}},["description"]="It's recommended to activate the Debug Mode to properly see every step and description.\010\010To start unlocking old Scholomance, you must first do a clear of Heroic Scholomance. Once done, go to the room that used to be Doctor Theolen Krastinov's room in the original Scholomance (top center room). At the top left portion of the room, use the Krastinov's Bag of Horrors toy. When you do, the ghost of Eva Sarkhoff will spawn, afraid of you (as the toy transforms you into the Butcher himself). Removing the toy's buff will make Eva realize you're not her murderer, and she will talk to you, giving you the old Spectral Essence trinket and allowing you to loot Eva's Femur on the ground. This allows you to see ghosts in Caer Darrow.\010\010Once you do, you can talk to Eva at her old spot outside Scholomance, where she will request you to look for her journal, as well as five candles, to perform a horrible ritual. The candles are traded from citizens in Caer Darrow, and require items they treasured when alive. Below, we have the locations for all items:",["expansionID"]=1,["headers"]={-75,-45},["instanceID"]=246,["localFacts"]={["cost"]={{"i",206355,1},{"i",206354,1},{"i",206358,1},{"i",206356,1},{"i",206346,1},{"i",206364,1},{"i",206357,1}},["description"]="It's recommended to activate the Debug Mode to properly see every step and description.\010\010To start unlocking old Scholomance, you must first do a clear of Heroic Scholomance. Once done, go to the room that used to be Doctor Theolen Krastinov's room in the original Scholomance (top center room). At the top left portion of the room, use the Krastinov's Bag of Horrors toy. When you do, the ghost of Eva Sarkhoff will spawn, afraid of you (as the toy transforms you into the Butcher himself). Removing the toy's buff will make Eva realize you're not her murderer, and she will talk to you, giving you the old Spectral Essence trinket and allowing you to loot Eva's Femur on the ground. This allows you to see ghosts in Caer Darrow.\010\010Once you do, you can talk to Eva at her old spot outside Scholomance, where she will request you to look for her journal, as well as five candles, to perform a horrible ritual. The candles are traded from citizens in Caer Darrow, and require items they treasured when alive. Below, we have the locations for all items:",["kind"]="Quest",["maps"]={22,23,317},["questID"]=76249,["record"]=334780},["mapID"]=306,["maps"]={22,23,317},["questID"]=76249},["76257"]={["awp"]=100105,["coords"]={["22"]={{69.07,72.96}}},["description"]="With 10.1.5, Blizzard readded the original version of Scholomance!\010\010Thank you, Blizzard!\010  -Crieve\010\010Here is how to get started:\010\0101. Obtain 'Krastinov's Bag of Horrors' from the rare spawn Doctor Theolen Krastinov in Scholomance, Heroic difficulty. This step can be skipped if you are accompanied by someone who already has the toy.\010\0102. Defeat Darkmaster Gandling in Headmaster's Retreat and enter the upper level centre room.\010\0103. Find a pile of bones on the ground in the southeastern part of the room, and use the toy 'Krastinov's Bag of Horrors'.\010\0104. Eva Sarkhoff should now have spawned, but you cannot interact with her before you remove the toy visage/buff named 'Surgical Alterations'.\010\0105. Accept Eva Sarkhoof's quest and her Inert Spectral Essence. Loot Eva's Femur from the pile of bones.\010\0106. Walk back upstairs to The Viewing Room. There are two bookcases in the southwestern corner of the room. Eva's Journal can be found on a middle shelf on the backside of the left bookcase.\010\0107. Obtain the reagents 3x Dark Runes and 5x Essence of Undeath and use the Inert Spectral Essence. Equip the crafted trinket 'Spectral Essence'.\010\0108. Obtain candles from doing objectives around Caer Darrow (outside Scholomance):\0108.1 Loot 'The Deed to Andorhal' from inside Andorhal Townhall at 43.35, 69.3, and give it to Magistrate Marduke at 70.5, 74.0.\0108.2 Loot 'Bucket of Fountain Water' from the candlelit fountain at 68.9, 78.8, and give it to Joseph Dirte at 68.0, 74.8.\0108.3 Loot 'Trampled Doll' from the meatwagon in Darrowshire at 35.7, 83.5. (Eastern Plaguelands!), return to Caer Darrow and give it to Sammy at 69.15, 78.7.\0108.4 Loot 'The Road Ahead' from a wall inside old Corin's Crossing tavern  at 55.0, 64.0. (Eastern Plaguelands!), return to Caer Darrow and give it to Artist Renfray at 65.8, 75.4.\0108.5 Loot 'Undelivered Shipment of Smokes' from a wagon behind the fountain at King's Square in Stratholme, return to Caer Darrow and give it to Rory at 63.4, 75.5.\010\0109. Use Eva's Journal to begin the ritual at 69.7, 71.7, inside Caer Darrow keep/open world Scholomance.",["expansionID"]=1,["headers"]={-75,-45},["instanceID"]=246,["localFacts"]={["kind"]="Quest",["qss"]={206373},["questID"]=76257,["record"]=334755},["mapID"]=306,["maps"]={307,308,309},["qss"]={206373},["questID"]=76257},["76261"]={["cost"]={{"i",206377,1},{"i",13180,1},{"i",12846,1}},["description"]="When you have both the ward and holy water, head to the entrance of the Crusader's Cathedral, but don't enter there - Instead, use your Ward of Naxxramas and turn to the left. If done correctly, you will see a Dread Ward of Naxxramas right next to the gates there, Once you find the Dread Ward, toss your  Stratholme Holy Water in it.\010\010If done correctly, you will receive a zone-wide yell, and a debuff called  Sleight of Hand. Once you get this debuff, you have 5 minutes to run all the way to the Undead side of Stratholme, to the gate to the left of the Necropolis where Lord Aurius Rivendare is located. You MUST kill Lord Aurius Rivendare to open the gate. If you arrive in time, a Hand of Naxxramas NPC will be there, and you will be able to use your Argent Dawn Commission to burn it to a crisp.",["headers"]={-732},["localFacts"]={["cost"]={{"i",206377,1},{"i",13180,1},{"i",12846,1}},["description"]="When you have both the ward and holy water, head to the entrance of the Crusader's Cathedral, but don't enter there - Instead, use your Ward of Naxxramas and turn to the left. If done correctly, you will see a Dread Ward of Naxxramas right next to the gates there, Once you find the Dread Ward, toss your  Stratholme Holy Water in it.\010\010If done correctly, you will receive a zone-wide yell, and a debuff called  Sleight of Hand. Once you get this debuff, you have 5 minutes to run all the way to the Undead side of Stratholme, to the gate to the left of the Necropolis where Lord Aurius Rivendare is located. You MUST kill Lord Aurius Rivendare to open the gate. If you arrive in time, a Hand of Naxxramas NPC will be there, and you will be able to use your Argent Dawn Commission to burn it to a crisp.",["kind"]="NPC",["maps"]={318},["npcID"]=206148,["questID"]=76261,["record"]=144884,["sourceQuests"]={76257}},["lvl"]=15,["mapID"]=23,["maps"]={318},["npcID"]=206148,["questID"]=76261,["sourceQuests"]={76257}},["76262"]={["coords"]={["23"]={{75.5,52.8}}},["description"]="Talk to Archmage after defeating Hand of Naxxramas",["headers"]={-732},["localFacts"]={["coords"]={["23"]={{75.5,52.8}}},["description"]="Talk to Archmage after defeating Hand of Naxxramas",["kind"]="NPC",["npcID"]=16116,["questID"]=76262,["record"]=144885,["sourceQuests"]={76261}},["lvl"]=15,["mapID"]=23,["maps"]={24},["npcID"]=16116,["questID"]=76262,["sourceQuests"]={76261}},["76263"]={["altQuests"]={76264,76265},["awp"]=30002,["coords"]={["23"]={{75.5,52.8}}},["cost"]={{"i",12811,1},{"i",14344,6},{"i",12363,5}},["description"]="1. Make sure you have equipped your Argent Dawn Commission, and enter Stratholme through the Main Gate.\010\0102. Kill mobs until Eye of Nazzramas spawns. Kill it and loot 'Ward of Naxxramas'.\010\0103. Interact with a Supply Crate to obtain 'Stratholme Holy Water'.\010\0104. Clear a path from Festival Lane through Market Row to Crusader's Square.\010\0105. Use your 'Ward of Naxxramas' in Crusader's square to obtain truesight and you should find a Dread Ward by the southern gate. (Prematurely killing any bosses in Undead Stratholme will prevent this spawn!)\010\0106. Use your 'Stratholme Holy Water' on the Dread Ward. This will trigger 'Sleight of Hand', and a five minute timer.\010\0107. You now have 5 minutes to do the following:\0107.1: Get back to Festival Lane and enter Elder's Square of the Undead seaction of Stratholme.\0107.2: Kill all bosses in Undead Stratholme. Remember to also take out the cultists inside the ziggurats.\0107.3: After killing Lord Aurius Rivendare in Slaughter Square, head into the southern gate where the Naxxramas portal is blocked off.\0107.4: An undead creature named 'Hand of Naxxramas' should be waiting for you, and an Extra Action Button should appear. Use it to burn the creature to dust before the timer tuns out.\010\0108. Travel to Light's Hope Chapel and find Archmage Angela Dosantos at 75.5, 52.8. Interact with her first, and she will offer a version of the quest named 'The Dread Citadel - Naxxramas' appropriate to your reputation with Argent Dawn. (Lower standing means she requires more gold and reagents from you, Exalted makes it free.)\010\0109. You have now unlocked the ability to obtain Corruptor's Scourgestones on an accound-wide basis, as well as a portal to Naxxramas at coordinates 35.7, 23.1.",["headers"]={-732,-45},["localFacts"]={["altQuests"]={76264,76265},["coords"]={["23"]={{75.5,52.8}}},["cost"]={{"i",12811,1},{"i",14344,6},{"i",12363,5}},["kind"]="Quest",["maxReputation"]={529,21000},["minReputation"]={529,9000},["qgs"]={16116},["questID"]=76263,["record"]=144887,["sourceQuests"]={76262}},["lvl"]=15,["mapID"]=23,["maps"]={24},["maxReputation"]={529,21000},["minReputation"]={529,9000},["qgs"]={16116},["questID"]=76263,["sourceQuests"]={76262}},["76264"]={["altQuests"]={76263,76265},["awp"]=30002,["coords"]={["23"]={{75.5,52.8}}},["cost"]={{"i",14344,3},{"i",12363,2}},["description"]="1. Make sure you have equipped your Argent Dawn Commission, and enter Stratholme through the Main Gate.\010\0102. Kill mobs until Eye of Nazzramas spawns. Kill it and loot 'Ward of Naxxramas'.\010\0103. Interact with a Supply Crate to obtain 'Stratholme Holy Water'.\010\0104. Clear a path from Festival Lane through Market Row to Crusader's Square.\010\0105. Use your 'Ward of Naxxramas' in Crusader's square to obtain truesight and you should find a Dread Ward by the southern gate. (Prematurely killing any bosses in Undead Stratholme will prevent this spawn!)\010\0106. Use your 'Stratholme Holy Water' on the Dread Ward. This will trigger 'Sleight of Hand', and a five minute timer.\010\0107. You now have 5 minutes to do the following:\0107.1: Get back to Festival Lane and enter Elder's Square of the Undead seaction of Stratholme.\0107.2: Kill all bosses in Undead Stratholme. Remember to also take out the cultists inside the ziggurats.\0107.3: After killing Lord Aurius Rivendare in Slaughter Square, head into the southern gate where the Naxxramas portal is blocked off.\0107.4: An undead creature named 'Hand of Naxxramas' should be waiting for you, and an Extra Action Button should appear. Use it to burn the creature to dust before the timer tuns out.\010\0108. Travel to Light's Hope Chapel and find Archmage Angela Dosantos at 75.5, 52.8. Interact with her first, and she will offer a version of the quest named 'The Dread Citadel - Naxxramas' appropriate to your reputation with Argent Dawn. (Lower standing means she requires more gold and reagents from you, Exalted makes it free.)\010\0109. You have now unlocked the ability to obtain Corruptor's Scourgestones on an accound-wide basis, as well as a portal to Naxxramas at coordinates 35.7, 23.1.",["headers"]={-732,-45},["localFacts"]={["altQuests"]={76263,76265},["coords"]={["23"]={{75.5,52.8}}},["cost"]={{"i",14344,3},{"i",12363,2}},["kind"]="Quest",["maxReputation"]={529,42000},["minReputation"]={529,21000},["qgs"]={16116},["questID"]=76264,["record"]=144889,["sourceQuests"]={76262}},["lvl"]=15,["mapID"]=23,["maps"]={24},["maxReputation"]={529,42000},["minReputation"]={529,21000},["qgs"]={16116},["questID"]=76264,["sourceQuests"]={76262}},["76265"]={["altQuests"]={76263,76264},["awp"]=30002,["coords"]={["23"]={{75.5,52.8}}},["description"]="1. Make sure you have equipped your Argent Dawn Commission, and enter Stratholme through the Main Gate.\010\0102. Kill mobs until Eye of Nazzramas spawns. Kill it and loot 'Ward of Naxxramas'.\010\0103. Interact with a Supply Crate to obtain 'Stratholme Holy Water'.\010\0104. Clear a path from Festival Lane through Market Row to Crusader's Square.\010\0105. Use your 'Ward of Naxxramas' in Crusader's square to obtain truesight and you should find a Dread Ward by the southern gate. (Prematurely killing any bosses in Undead Stratholme will prevent this spawn!)\010\0106. Use your 'Stratholme Holy Water' on the Dread Ward. This will trigger 'Sleight of Hand', and a five minute timer.\010\0107. You now have 5 minutes to do the following:\0107.1: Get back to Festival Lane and enter Elder's Square of the Undead seaction of Stratholme.\0107.2: Kill all bosses in Undead Stratholme. Remember to also take out the cultists inside the ziggurats.\0107.3: After killing Lord Aurius Rivendare in Slaughter Square, head into the southern gate where the Naxxramas portal is blocked off.\0107.4: An undead creature named 'Hand of Naxxramas' should be waiting for you, and an Extra Action Button should appear. Use it to burn the creature to dust before the timer tuns out.\010\0108. Travel to Light's Hope Chapel and find Archmage Angela Dosantos at 75.5, 52.8. Interact with her first, and she will offer a version of the quest named 'The Dread Citadel - Naxxramas' appropriate to your reputation with Argent Dawn. (Lower standing means she requires more gold and reagents from you, Exalted makes it free.)\010\0109. You have now unlocked the ability to obtain Corruptor's Scourgestones on an accound-wide basis, as well as a portal to Naxxramas at coordinates 35.7, 23.1.",["headers"]={-732,-45},["localFacts"]={["altQuests"]={76263,76264},["coords"]={["23"]={{75.5,52.8}}},["kind"]="Quest",["minReputation"]={529,42000},["qgs"]={16116},["questID"]=76265,["record"]=144891,["sourceQuests"]={76262}},["lvl"]=15,["mapID"]=23,["maps"]={24},["minReputation"]={529,42000},["qgs"]={16116},["questID"]=76265,["sourceQuests"]={76262}},["76307"]={["awp"]=100105,["b"]=1,["coords"]={["23"]={{35.7,22.9}},["115"]={{87.4,51.1}}},["cost"]={{"i",206472,1},{"i",206470,1},{"i",206471,1}},["description"]="1. First you need to create a Makeshift Grappling Hook from the following items:\010\0101.1 Abomination's Chain can be fished from any slime (green liquid), like the small pool just inside Arachnid Quarter.\010\0101.2 Faerlina's Sewing Kit drops from Grand Widow Faerlina in the Arachnid Quarter.\010\0101.3 Construct's Hook can be found on a handle under a vat of slime on the right side of the second room of the Construct Quarter.\010\0102. Use your Makeshift Grappling Hook to get access to grapple points inside Naxxramas on an account-wide basis.\010\010",["expansionID"]=3,["headers"]={-75,-55},["instanceID"]=754,["isRaid"]=1,["localFacts"]={["b"]=1,["cost"]={{"i",206472,1},{"i",206470,1},{"i",206471,1}},["itemID"]=206473,["kind"]="CharacterUnlockQuest",["questID"]=76307,["record"]=341366,["sourceQuests"]={76263,76264,76265},["spellID"]=413668},["mapID"]=162,["maps"]={163,164,165,166,167},["questID"]=76307,["sourceQuests"]={76263,76264,76265},["spellID"]=413668},["76390"]={["awp"]=100105,["coords"]={["23"]={{35.7,22.9}},["115"]={{87.4,51.1}}},["cost"]={{"i",13180,2},{"i",33042,1},{"i",20520,3},{"i",206375,5},{"i",206374,20}},["description"]="1. Kill all bosses in Construct Quarter, and walk back to the entrance of The Halls of Reanimation.\010\0102. Walk up the slope to the platform on left side, and you should see two Grapple Point on two ledges to the left side. Grapple to the southern ledge.\010\0103. Speed-jump (Burning Rush/Speed potion) to the platform northeast of the ledge, and position yourself such that you are facing the corresponding platform to the northern ledge. Said platform is connected to a wall structure with two windows on the top. The left window ledge is the location of the next grappling point. Grapple up to it.\010\0104. Jump down to the brown ledge following the wall in a northeastern direction and around the corner, then over the skull on the wall, and back in a southeastern direction. The next grapple point is across the gap to a window ledge on left side, grapple to it.\010\0105. Follow the ledge in a southwestern direction and around the corner. You should see two pipe ends on the wall in front of you, the next grappling point on the left pipe. Grapple to it.\010\0106. Facing the position you grappled from, you should see Zackett Skullsmash on a window ledge. Jump down to the NPC.\010\0107. Use Stratholme Holy Water on Zackett Skullsmash and accept the quest Inconvenience Fee. You should have all required items on you and be able to turn it in immediately. This unlocks Zackett Skullsmash on an account-wide basis, and the Goblin will move to the central ring.\010\0108. You can safely get down by jumping down to the ledge above the entrance to the room, and leave through the Naxxramas Portal located where you killed Thaddius.\010\010",["expansionID"]=3,["headers"]={-75,-45},["instanceID"]=754,["isRaid"]=1,["localFacts"]={["cost"]={{"i",13180,2},{"i",33042,1},{"i",20520,3},{"i",206375,5},{"i",206374,20}},["kind"]="Quest",["qgs"]={206572},["questID"]=76390,["record"]=341432,["sourceQuests"]={76307}},["mapID"]=162,["maps"]={163,164,165,166,167},["qgs"]={206572},["questID"]=76390,["sourceQuests"]={76307}},["76552"]={["awp"]=100105,["coords"]={["2025"]={{53.7,87.7}}},["headers"]={-732,-401,-45},["localFacts"]={["coords"]={["2025"]={{53.7,87.7}}},["kind"]="Quest",["lvl"]=70,["qgs"]={204990},["questID"]=76552,["record"]=228837,["sourceQuests"]={74476,74942}},["lvl"]=70,["mapID"]=2025,["qgs"]={204990},["questID"]=76552,["sourceQuests"]={74476,74942}},["77237"]={["awp"]=100105,["coords"]={["2112"]={{26.6,53.9}}},["crs"]={207697},["description"]="***Using Debug Mode is recommended.***\010",["expansionID"]=10,["headers"]={-50,-505,-45},["localFacts"]={["coords"]={["2112"]={{26.6,53.9}}},["crs"]={207697},["kind"]="Quest",["lvl"]=10,["qss"]={207827},["questID"]=77237,["record"]=291132},["lvl"]=10,["qss"]={207827},["questID"]=77237},["77241"]={["awp"]=100105,["coords"]={["2025"]={{51,57}}},["headers"]={-732,-402,-45},["localFacts"]={["coords"]={["2025"]={{51,57}}},["kind"]="Quest",["lvl"]=70,["minReputation"]={2553,2},["qgs"]={204450},["questID"]=77241,["record"]=229498},["lvl"]=70,["mapID"]=2025,["maps"]={2199},["minReputation"]={2553,2},["qgs"]={204450},["questID"]=77241},["77282"]={["awp"]=100105,["coords"]={["2022"]={{54.6,20.4}}},["description"]="***Using Debug Mode is recommended.***\010",["expansionID"]=10,["headers"]={-50,-505,-45},["localFacts"]={["coords"]={["2022"]={{54.6,20.4}}},["kind"]="Quest",["lvl