]=32566,["lineage"]={{["b"]=1,["itemID"]=32566,["kind"]="Toy",["record"]=329669,["u"]=9}},["localFacts"]={["b"]=1,["itemID"]=32566,["kind"]="Toy",["record"]=329669,["u"]=9},["u"]=9},["id"]="att-32566-9aeef447e062",["guideIds"]={}}}},{["toyId"]=99,["itemId"]=32782,["name"]="Time-Lost Figurine",["icon"]="inv_qirajidol_war",["routes"]={{["path"]={"The Burning Crusade","Rare"},["id"]="item-32782:route-1",["availability"]="ongoing",["guideIds"]={},["summaryOnly"]=true},{["path"]={"Retail","Zones"},["attId"]="att-32782-1ee9659d91ab",["availability"]="ongoing",["source"]="https://github.com/ATTWoWAddon/AllTheThings/blob/52895ee664b61e08f091d514fe1556568d411570/db/Standard/Categories/Zones.lua",["facts"]={["awp"]=20003,["b"]=1,["category"]="Zones",["coords"]={["108"]={{66.2,77.5}}},["cost"]={{"i",32720,1}},["description"]="The process to summon this boss is as follows.\010\0101. Collect Shadow Dust from mobs in Skettis.\0102. Turn in 6 Shadow Dust to Severin for the quest More Shadow Dust to obtain Elixir of Shadows.\0103. Drink the elixir to gain a 20-minute buff that allows you to see Time-Lost mobs around Skettis.\0104. Kill these mobs to obtain Time-Lost Scrolls (40 required per summon).\0105. Make sure you are on the Adversarial Blood quest if this is your first time; it begins with the quest Ishaal's Almanac.\0106. Go to a skull pile and use 10 Time-Lost Scrolls to summon boss. (Darkscreecher Akkarai [Akkarai's Talons], Karrog [Karrog's Spine], Gezzarak the Huntress [Gezzarak's Claws], Vakkiz the Windrager [Vakkiz's Scale]).\0107. Take these 4 items to Hazzik to complete Adversarial Blood which rewards a Time-Lost Offering.\0108. Use the Time-Lost Offering at the Ancient Skull Pile on middle island to summon Terokk. (It has about a 15-minute spawn timer)",["headers"]={-732,-46},["itemId"]=32782,["lineage"]={{["coords"]={["108"]={{66.2,77.5}}},["cost"]={{"i",32720,1}},["description"]="The process to summon this boss is as follows.\010\0101. Collect Shadow Dust from mobs in Skettis.\0102. Turn in 6 Shadow Dust to Severin for the quest More Shadow Dust to obtain Elixir of Shadows.\0103. Drink the elixir to gain a 20-minute buff that allows you to see Time-Lost mobs around Skettis.\0104. Kill these mobs to obtain Time-Lost Scrolls (40 required per summon).\0105. Make sure you are on the Adversarial Blood quest if this is your first time; it begins with the quest Ishaal's Almanac.\0106. Go to a skull pile and use 10 Time-Lost Scrolls to summon boss. (Darkscreecher Akkarai [Akkarai's Talons], Karrog [Karrog's Spine], Gezzarak the Huntress [Gezzarak's Claws], Vakkiz the Windrager [Vakkiz's Scale]).\0107. Take these 4 items to Hazzik to complete Adversarial Blood which rewards a Time-Lost Offering.\0108. Use the Time-Lost Offering at the Ancient Skull Pile on middle island to summon Terokk. (It has about a 15-minute spawn timer)",["kind"]="NPC",["npcID"]=21838,["providers"]={{"o",185928}},["record"]=160125},{["b"]=1,["itemID"]=32782,["kind"]="Toy",["record"]=160134}},["localFacts"]={["b"]=1,["itemID"]=32782,["kind"]="Toy",["record"]=160134},["lvl"]=15,["mapID"]=108,["npcID"]=21838,["providers"]={{"o",185928}}},["id"]="att-32782-1ee9659d91ab",["guideIds"]={"att-32782-1ee9659d91ab"}}}},{["toyId"]=30,["itemId"]=33079,["name"]="Murloc Costume",["icon"]="inv_misc_head_murloc_01",["routes"]={{["path"]={"Promotion","Blizzcon"},["resale"]=true,["id"]="item-33079:route-1",["availability"]="external",["guideIds"]={},["summaryOnly"]=true},{["path"]={"Retail","Promotions"},["attId"]="att-33079-e7434078a2cd",["availability"]="external",["source"]="https://github.com/ATTWoWAddon/AllTheThings/blob/52895ee664b61e08f091d514fe1556568d411570/db/Standard/Categories/Promotions.lua",["facts"]={["awp"]=20103,["b"]=1,["category"]="Promotions",["headers"]={-736,-520},["itemId"]=33079,["lineage"]={{["awp"]=20103,["b"]=1,["itemID"]=33079,["kind"]="Toy",["record"]=299594,["u"]=2}},["localFacts"]={["awp"]=20103,["b"]=1,["itemID"]=33079,["kind"]="Toy",["record"]=299