79,-16},["itemId"]=50471,["lineage"]={{["awp"]=30300,["e"]=9,["kind"]="NPC",["maps"]={310,311,312,313,314,315,316},["npcID"]=36296,["record"]=55354},{["b"]=1,["e"]=9,["itemID"]=54537,["kind"]="Item",["record"]=55362},{["b"]=1,["e"]=9,["itemID"]=50471,["kind"]="Toy",["record"]=55376}},["localFacts"]={["b"]=1,["e"]=9,["itemID"]=50471,["kind"]="Toy",["record"]=55376},["maps"]={310,311,312,313,314,315,316},["npcID"]=36296},["id"]="att-50471-0ba720e06b0b",["guideIds"]={}}}},{["toyId"]=112,["itemId"]=52201,["name"]="Muradin's Favor",["icon"]="spell_frost_frostward",["routes"]={{["path"]={"Wrath of the Lich King","Raid"},["id"]="item-52201:route-1",["availability"]="ongoing",["guideIds"]={},["summaryOnly"]=true},{["path"]={"Retail","Instances"},["attId"]="att-52201-17c27056d701",["availability"]="ongoing",["source"]="https://github.com/ATTWoWAddon/AllTheThings/blob/52895ee664b61e08f091d514fe1556568d411570/db/Standard/Categories/Instances.lua",["facts"]={["awp"]=30300,["b"]=1,["c"]={1,2,6},["category"]="Instances",["coords"]={["118"]={{53.7,87}}},["description"]="Muradin: Oh lad, how I missed those endless days in Lordaeron, sharpening your skill with this dull blade. Forging you into a weapon meant to withstand the demands of a great destiny. Heh… You sure put them skills to use, didn't you lad?\010\010If only I'd been able to stop you that day, how different things migha' been. If only I'da never discovered that accursed blade. Farewell, Arthas, my brother.",["expansionID"]=3,["headers"]={-75},["instanceID"]=758,["isRaid"]=1,["itemId"]=52201,["lineage"]={{["awp"]=30300,["coords"]={["118"]={{53.7,87}}},["instanceID"]=758,["isRaid"]=1,["kind"]="Instance",["mapID"]=186,["maps"]={187,188,189,190,191,192,193,699,1359},["record"]=344078},{["b"]=1,["c"]={1,2,6},["description"]="Dropped by the Lich King on 25-Man difficulty while on the quest |cFFefc400The Lich King's Last Stand|r. Only your first kill will trigger the item to drop. You do NOT need to have Shadowmourne equipped.\010\010This item contains a lot of BoE cosmetic items that sell very well. During its time, this was used to reward other members of the raid for assisting the guild master (more than likely) with Shadowmourne for the many months it took to complete the quest chain.\010\010In addition to being very rewarding, these quests were some of the most treasured throughout World of Warcraft's long history.",["itemID"]=51315,["kind"]="Item",["lvl"]=30,["providers"]={{"i",51316}},["qgs"]={36597},["questID"]=24914,["record"]=344094,["sourceQuests"]={24549}},{["b"]=1,["description"]="Muradin: Oh lad, how I missed those endless days in Lordaeron, sharpening your skill with this dull blade. Forging you into a weapon meant to withstand the demands of a great destiny. Heh… You sure put them skills to use, didn't you lad?\010\010If only I'd been able to stop you that day, how different things migha' been. If only I'da never discovered that accursed blade. Farewell, Arthas, my brother.",["itemID"]=51319,["kind"]="Item",["lvl"]=30,["questID"]=24917,["record"]=344097},{["itemID"]=52201,["kind"]="Toy",["lvl"]=10,["record"]=344098}},["localFacts"]={["itemID"]=52201,["kind"]="Toy",["lvl"]=10,["record"]=344098},["lvl"]=10,["mapID"]=186,["maps"]={187,188,189,190,191,192,193,699,1359},["providers"]={{"i",51316}},["questID"]=24917},["id"]="att-52201-17c27056d701",["guideIds"]={"att-52201-17c27056d701"}}}},{["toyId"]=114,["itemId"]=52253,["name"]="Sylvanas' Music Box",["icon"]="inv_misc_enggizmos_18",["routes"]={{["path"]={"Wrath of the Lich King","Raid"},["id"]="item-52253:route-1",["availability"]="ongoing",["guideIds"]={},["summaryOnly"]=true},{["path"]={"Retail","Instances"},["attId"]="att-52253-4c2cda79301a",["availability"]="ongoing",["source"]="https://github.com/ATTWoWAddon/AllTheThings/blob/52895ee664b61e08f091d514fe1556568d411570/db/Standard/Categories/Instances.lua",["facts"]={["awp"]=30300,["b"]=1,["c"]={1,2,6},["category"]="Instances",["coords"]={["118"]={{53.7,87}}},["description"]="Sylvanas: So, it is done. I had not dared to trust my senses. Too many times has the Lich King made me to be a fool. Finally, he has been made to pay for the atrocities he imposed upon my people.\010\010May Azeroth never fail to remember the horrible price we paid for our weakness, for our pride. But what now, Hero? What of those freed from his grasp but still shackled to their mortal coils?\010\010Leave me. I have much to ponder.",["expansionID"]=3,["headers"]={-75},["instanceID"]=758,["isRaid"]=1,["itemId"]=52253,["lineage"]={{["awp"]=30300,["coords"]={["118"]={{53.7,87}}},["instanceID"]=758,["isRaid"]=1,["kind"]="Instance",["mapID"]=186,["maps"]={187,188,189,190,191,192,193,699,1359},["record"]=344078},{["b"]=1,["c"]={1,2,6},["description"]="Dropped by the Lich King on 25-Man difficulty while on the quest |cFFefc400The Lich King's Last Stand|r. Only your first kill will trigger the item to drop. You do NOT need to have Shadowmourne equipped.\010\010This item contains a lot of BoE cosmetic items that sell very well. During its time, this was used to reward other members of the raid for assisting the guild master (more than likely) with Shadowmourne for the many months it took to complete the quest chain.\010\010In addition to being very rewarding, these quests were some of the most treasured throughout World of Warcraft's long history.",["itemID"]=51315,["kind"]="Item",["lvl"]=30,["providers"]={{"i",51316}},["qgs"]={36597},["questID"]=24914,["record"]=344094,["sourceQuests"]={24549}},{["b"]=1,["description"]="Sylvanas: So, it is done. I had not dared to trust my senses. Too many times has the Lich King made me to be a fool. Finally, he has been made to pay for the atrocities he imposed upon my people.\010\010May Azeroth never fail to remember the horrible price we paid for our weakness, for our pride. But what now, Hero? What of those freed from his grasp but still shackled to their mortal coils?\010\010Leave me. I have much to ponder.",["itemID"]=51321,["kind"