63},["itemId"]=140363,["lineage"]={{["description"]="Players with some sort of Sense Demons ability could get this mob to spawn from Doomsayers.",["kind"]="NPC",["npcID"]=112315,["record"]=257056,["u"]=2},{["itemID"]=140363,["kind"]="Toy",["record"]=257057,["u"]=2}},["localFacts"]={["itemID"]=140363,["kind"]="Toy",["record"]=257057,["u"]=2},["npcID"]=112315,["u"]=2},["id"]="att-140363-7183b77fc9a0",["guideIds"]={}},{["path"]={"Retail","WorldEvents"},["attId"]="att-140363-b957a3bbf54d",["availability"]="removed",["source"]="https://github.com/ATTWoWAddon/AllTheThings/blob/52895ee664b61e08f091d514fe1556568d411570/db/Standard/Categories/WorldEvents.lua",["facts"]={["awp"]=70003,["category"]="WorldEvents",["description"]="This Toy, Pocket Fel Spreader is available EXCLUSIVELY during the Legion pre-expansion event. It is obtained by using any ability or item that allows you to detect demons, and then speaking to a Doomsayer. \010When using any such ability or item, the Doomsayer will sometimes have the dialogue option \"There's something not quite right about you...\". Selecting this option, when visible, will change the Doomsayer into a Dread Infiltrator, which can be killed and looted to obtain this Toy. Note that the Toy is NOT a guaranteed drop, but has a roughly 25% drop rate.",["expansionID"]=7,["headers"]={-734,-103,-46},["itemId"]=140363,["lineage"]={{["description"]="This Toy, Pocket Fel Spreader is available EXCLUSIVELY during the Legion pre-expansion event. It is obtained by using any ability or item that allows you to detect demons, and then speaking to a Doomsayer. \010When using any such ability or item, the Doomsayer will sometimes have the dialogue option \"There's something not quite right about you...\". Selecting this option, when visible, will change the Doomsayer into a Dread Infiltrator, which can be killed and looted to obtain this Toy. Note that the Toy is NOT a guaranteed drop, but has a roughly 25% drop rate.",["kind"]="NPC",["npcID"]=112527,["record"]=257002,["u"]=2},{["itemID"]=140363,["kind"]="Toy",["record"]=257003,["u"]=2}},["localFacts"]={["itemID"]=140363,["kind"]="Toy",["record"]=257003,["u"]=2},["npcID"]=112527,["u"]=2},["id"]="att-140363-b957a3bbf54d",["guideIds"]={}},{["path"]={"Retail","WorldEvents"},["attId"]="att-140363-375e7c96bd40",["availability"]="removed",["source"]="https://github.com/ATTWoWAddon/AllTheThings/blob/52895ee664b61e08f091d514fe1556568d411570/db/Standard/Categories/WorldEvents.lua",["facts"]={["awp"]=70003,["category"]="WorldEvents",["description"]="This Toy, Pocket Fel Spreader is available EXCLUSIVELY during the Legion pre-expansion event. It is obtained by using any ability or item that allows you to detect demons, and then speaking to a Doomsayer. \010When using any such ability or item, the Doomsayer will sometimes have the dialogue option \"There's something not quite right about you...\". Selecting this option, when visible, will change the Doomsayer into a Dread Infiltrator, which can be killed and looted to obtain this Toy. Note that the Toy is NOT a guaranteed drop, but has a roughly 25% drop rate.\010",["expansionID"]=7,["headers"]={-734,-103,-46},["itemId"]=140363,["lineage"]={{["description"]="This Toy, Pocket Fel Spreader is available EXCLUSIVELY during the Legion pre-expansion event. It is obtained by using any ability or item that allows you to detect demons, and then speaking to a Doomsayer. \010When using any such ability or item, the Doomsayer will sometimes have the dialogue option \"There's something not quite right about you...\". Selecting this option, when visible, will change the Doomsayer into a Dread Infiltrator, which can be killed and looted to obtain this Toy. Note that the Toy is NOT a guaranteed drop, but has a roughly 25% drop rate.\010",["kind"]="NPC",["npcID"]=112198,["record"]=257004,["u"]=2},{["itemID"]=140363,["kind"]="Toy",["record"]=257005,["u"]=2}},["localFacts"]={["itemID"]=140363,["kind"]="Toy",["record"]=257005,["u"]=2},["npcID"]=1