["lvl"]=10,["record"]=197237},["lvl"]=10,["mapID"]=680,["maps"]={692,693},["objectID"]=252452,["qgs"]={97140,115736},["questID"]=43943},["id"]="att-141306-0aacb3521f82",["guideIds"]={"att-141306-0aacb3521f82"}}}},{["toyId"]=582,["itemId"]=141331,["name"]="Vial of Green Goo",["icon"]="inv_potion_22",["routes"]={{["path"]={"Legion","Rare"},["id"]="item-141331:route-1",["availability"]="ongoing",["guideIds"]={},["summaryOnly"]=true},{["path"]={"Retail","Instances"},["attId"]="att-141331-5471fa8b03f8",["availability"]="ongoing",["source"]="https://github.com/ATTWoWAddon/AllTheThings/blob/52895ee664b61e08f091d514fe1556568d411570/db/Standard/Categories/Instances.lua",["facts"]={["awp"]=70003,["b"]=1,["category"]="Instances",["coords"]={["30"]={{30.1,74.6}}},["description"]="|cff3399ffSTEP 1:|r Kill the last boss in Gnomeregan.\010|cff3399ffSTEP 2:|r Go to the back of the pillar on the left side of the room's entrance, and press the small button.\010|cff3399ffSTEP 3:|r Endgineer Omegaplugg will spawn, and his health scales to max level.\010|cff3399ffSTEP 4:|r To stop the bombs from spawning, you must disable the conduits in the room by pressing all the large red buttons in a counterclockwise format. (This is the first conduit on the right as you enter the room.)\010|cff3399ffSTEP 5:|r Kill the boss, and all players can loot the toy. Good luck, have fun!",["expansionID"]=1,["headers"]={-75},["instanceID"]=231,["itemId"]=141331,["lineage"]={{["coords"]={["30"]={{30.1,74.6}}},["description"]="Horde players can access Gnomeregan from the teleporter in Grom'gol Base Camp, Northern Stranglethorn.",["instanceID"]=231,["kind"]="Instance",["mapID"]=226,["maps"]={227,228,229},["record"]=333336},{["awp"]=70100,["description"]="|cff3399ffSTEP 1:|r Kill the last boss in Gnomeregan.\010|cff3399ffSTEP 2:|r Go to the back of the pillar on the left side of the room's entrance, and press the small button.\010|cff3399ffSTEP 3:|r Endgineer Omegaplugg will spawn, and his health scales to max level.\010|cff3399ffSTEP 4:|r To stop the bombs from spawning, you must disable the conduits in the room by pressing all the large red buttons in a counterclockwise format. (This is the first conduit on the right as you enter the room.)\010|cff3399ffSTEP 5:|r Kill the boss, and all players can loot the toy. Good luck, have fun!",["kind"]="NPC",["npcID"]=113621,["record"]=333509},{["awp"]=70003,["b"]=1,["itemID"]=141331,["kind"]="Toy",["record"]=333510}},["localFacts"]={["awp"]=70003,["b"]=1,["itemID"]=141331,["kind"]="Toy",["record"]=333510},["mapID"]=226,["maps"]={227,228,229},["npcID"]=113621},["id"]="att-141331-5471fa8b03f8",["guideIds"]={"walkthrough-authored-141331"},["canonicalRouteId"]="walkthrough-authored-141331"}}},{["toyId"]=1575,["itemId"]=141605,["name"]="Flight Master's Whistle",["icon"]="ability_hunter_beastcall",["routes"]={{["path"]={"Legion","Quest"},["id"]="item-141605:route-1",["availability"]="ongoing",["guideIds"]={},["summaryOnly"]=true},{["path"]={"Retail","ExpansionFeatures"},["attId"]="att-141605-697051a62877",["availability"]="ongoing",["source"]="https://github.com/ATTWoWAddon/AllTheThings/blob/52895ee664b61e08f091d514fe1556568d411570/db/Standard/Categories/ExpansionFeatures.lua",["facts"]={["altQuests"]={52450},["awp"]=80100,["b"]=1,["category"]="ExpansionFeatures",["coords"]={["1161"]={{69.4,27}}},["expansionID"]=8,["headers"]={-735,-148,-146,-45},["itemId"]=141605,["lineage"]={{["altQuests"]={52450},["coords"]={["1161"]={{69.4,27}}},["kind"]="Quest",["lvl"]=50,["qgs"]={135612},["questID"]=51918,["r"]=2,["record"]=100356,["sourceQuests"]={52654,53063}},{["b"]=1,["itemID"]=141605,["kind"]="Toy",["record"]=100358}},["localFacts"]={["b"]=1,["itemID"]=141605,["kind"]="Toy",["record"]=100358},["lvl"]=50,["qgs"]={135612},["questID"]=51918,["r"]=2,["sourceQuests"]={52654,53063}},["id"]="att-141605-697051a62877",["guideIds"]={"att-141605-697051a62877"}},{["path"]={"Retail","Zones"},["attId"]="att-141605-4436dfe5c5c6",["availability"]="ongoing",[