={["2339"]={{48.07,52.16}}},["kind"]="NPC",["npcID"]=234746,["record"]=280744,["u"]=2},{["b"]=1,["cost"]={{"c",2032,10}},["itemID"]=206347,["kind"]="Toy",["record"]=280780,["u"]=2}},["localFacts"]={["b"]=1,["cost"]={{"c",2032,10}},["itemID"]=206347,["kind"]="Toy",["record"]=280780,["u"]=2},["npcID"]=234746,["rwp"]=120001,["u"]=2},["id"]="att-206347-fedb860e3ffb",["guideIds"]={}},{["path"]={"Retail","TradingPost"},["attId"]="att-206347-5533643004f2",["availability"]="removed",["source"]="https://github.com/ATTWoWAddon/AllTheThings/blob/52895ee664b61e08f091d514fe1556568d411570/db/Standard/Categories/TradingPost.lua",["facts"]={["awp"]=120100,["b"]=1,["category"]="TradingPost",["coords"]={["2393"]={{50.9,77.5}}},["cost"]={{"c",2032,10}},["headers"]={-230,-339,-332,-58},["itemId"]=206347,["lineage"]={{["coords"]={["2393"]={{50.9,77.5}}},["kind"]="NPC",["npcID"]=268180,["record"]=281711,["u"]=2},{["b"]=1,["cost"]={{"c",2032,10}},["itemID"]=206347,["kind"]="Toy",["record"]=281774,["u"]=2}},["localFacts"]={["b"]=1,["cost"]={{"c",2032,10}},["itemID"]=206347,["kind"]="Toy",["record"]=281774,["u"]=2},["npcID"]=268180,["rwp"]=120100,["u"]=2},["id"]="att-206347-5533643004f2",["guideIds"]={}}}},{["toyId"]=1335,["itemId"]=206565,["name"]="Plagued Grain",["icon"]="inv_crate_05",["routes"]={{["path"]={"Classic","Vendor"},["id"]="item-206565:route-1",["availability"]="ongoing",["guideIds"]={},["summaryOnly"]=true},{["path"]={"Retail","Instances"},["attId"]="att-206565-5e29d982ab7f",["availability"]="ongoing",["source"]="https://github.com/ATTWoWAddon/AllTheThings/blob/52895ee664b61e08f091d514fe1556568d411570/db/Standard/Categories/Instances.lua",["facts"]={["awp"]=100105,["b"]=1,["category"]="Instances",["coords"]={["23"]={{35.7,22.9}},["115"]={{87.4,51.1}}},["cost"]={{"i",206576,15}},["description"]="1. Kill all bosses in Construct Quarter, and walk back to the entrance of The Halls of Reanimation.\010\0102. Walk up the slope to the platform on left side, and you should see two Grapple Point on two ledges to the left side. Grapple to the southern ledge.\010\0103. Speed-jump (Burning Rush/Speed potion) to the platform northeast of the ledge, and position yourself such that you are facing the corresponding platform to the northern ledge. Said platform is connected to a wall structure with two windows on the top. The left window ledge is the location of the next grappling point. Grapple up to it.\010\0104. Jump down to the brown ledge following the wall in a northeastern direction and around the corner, then over the skull on the wall, and back in a southeastern direction. The next grapple point is across the gap to a window ledge on left side, grapple to it.\010\0105. Follow the ledge in a southwestern direction and around the corner. You should see two pipe ends on the wall in front of you, the next grappling point on the left pipe. Grapple to it.\010\0106. Facing the position you grappled from, you should see Zackett Skullsmash on a window ledge. Jump down to the NPC.\010\0107. Use Stratholme Holy Water on Zackett Skullsmash and accept the quest Inconvenience Fee. You should have all required items on you and be able to turn it in immediately. This unlocks Zackett Skullsmash on an account-wide basis, and the Goblin will move to the central ring.\010\0108. You can safely get down by jumping down to the ledge above the entrance to the room, and leave through the Naxxramas Portal located where you killed Thaddius.\010\010",["expansionID"]=3,["headers"]={-75},["instanceID"]=754,["isRaid"]=1,["itemId"]=206565,["lineage"]={{["awp"]=30002,["coords"]={["23"]={{35.7,22.9}},["115"]={{87.4,51.1}}},["description"]="Make sure you go through 'Wards of the Dread Citadel' prior to farming this raid, then you will be able to obtain Scourgestones and special reagents during your grind. See the respective header for more information.",["instanceID"]=754,["isRaid"]=1,["kind"]="Instance",["mapID"]=162,["maps"]={163,164,165,166,167},["record"]=340719},{["kind"]="NPC",["npcID"]=206572,["record"]=341368,["sourceQuests"]={76390}},{["b"]=1,["cost"]={{"i",206576,15}},["itemID"]=206565,["kind"]="Toy",["record"]=341393}},["localFacts"]={["b"]=1,["cost"]={{"i",206576,15}},["itemID"]=206565,["kind"]="Toy",["record"]=341393},["mapID"]=162,["maps"]={163,164,165,166,167},["npcID"]=206572,["sourceQuests"]={76390}},["id"]="att-206565-5e29d982ab7f",["guideIds"]={"att-206565-5e29d982ab7f"}}}},{["toyId"]=1341,["itemId"]=206696,["name"]="Tricked-Out Thinking Cap",["icon"]="inv_helm_armor_gnomish_c_01_blue",["routes"]={{["path"]={"Dragonflight","Riddle"},["id"]="item-206696:route-1",["availability"]="ongoing",["guideIds"]={},["summaryOnly"]=true},{["path"]={"Retail","Secrets"},["attId"]="att-206696-eafcb5ee7f26",["availability"]="ongoing",["source"]="https://github.com/ATTWoWAddon/AllTheThings/blob/52895ee664b61e08f091d514fe1556568d411570/db/Standard/Categories/Secrets.lua",["facts"]={["awp"]=100105,["b"]=1,["category"]="Secrets",["coords"]={["2112"]={{26.6,53.9}}},["crs"]={207697},["description"]="***Using Debug Mode is recommended.***\010",["expansionID"]=10,["headers"]={-50,-505,-45},["itemId"]=206696,["lineage"]={{["coords"]={["2112"]={{26.6,53.9}}},["crs"]={207697},["kind"]="Quest",["lvl"]=10,["qss"]={207827},["questID"]=77237,["record"]=291132},{["b"]=1,["itemID"]=206696,["kind"]="Toy",["record"]=291133}},["localFacts"]={["b"]=1,["itemID"]=206696,["kind"]="Toy",["record"]=291133},["lvl"]=10,["qss"]={207827},["questID"]=77237},["id"]="att-206696-eafcb5ee7f26",["guideIds"]={"att-206696-eafcb5ee7f26"}},{["path"]={"Retail","Holidays"},["attId"]="att-206696-ef0a8f20f9ee",["availability"]="unknown",["source"]="https://github.com/ATTWoWAddon/AllTheThings/blob/52895ee664b61e08f091d514fe1556568d411570/db/Standard/Categories/Holidays.lua",["facts"]={["awp"]=110005,["b"]=1,["category"]="Holidays",["coords"]={["71"]={{63.3,52.4}}},["description"]="***Using Debug Mode is recommended.***\010",["difficultyID"]=19,["e"]=242,["headers"]={-36,-592,-609,-5