d"]=263975}}}},{["id"]="att-263975-669435f63a38:kystia",["kind"]="objective",["text"]="Clear the opening market route to Kystia Manaheart. Damage hostile Nibbles until the mana wyrm returns to light form, then attack Kystia while she is destabilized. Interrupt Mirror Images and avoid Fel Spray.",["sources"]={"https://github.com/ATTWoWAddon/AllTheThings/blob/52895ee664b61e08f091d514fe1556568d411570/db/Standard/Categories/Instances.lua","https://www.wowhead.com/achievement=62388","https://www.wowhead.com/item=263975","https://www.wowhead.com/npc=252458"},["recovery"]={["text"]="Recheck the named room, selected difficulty and current game objectives. Continue advances only the guide cursor; it never records a kill, unlock, purchase or ownership."},["manual"]=true,["completeWhen"]={["any"]={{["kind"]="itemCount",["itemId"]=263975,["quantity"]=1},{["kind"]="toyOwned",["itemId"]=263975}}},["after"]={"att-263975-669435f63a38:normal-entry"}},{["id"]="att-263975-669435f63a38:roles",["kind"]="interact",["text"]="After the first boss, climb to the Illicit Rain service area and speak to its event NPC for a disguise/role. Assign the group’s serving, sweeping, dancing and bouncer jobs before beginning.",["sources"]={"https://github.com/ATTWoWAddon/AllTheThings/blob/52895ee664b61e08f091d514fe1556568d411570/db/Standard/Categories/Instances.lua","https://www.wowhead.com/achievement=62388","https://www.wowhead.com/item=263975","https://www.wowhead.com/npc=252458"},["recovery"]={["text"]="If no disguise is offered, verify that this is a real-player Normal-or-higher run. Do not continue farther into the dungeon expecting the final boss to drop this toy."},["manual"]=true,["completeWhen"]={["any"]={{["kind"]="itemCount",["itemId"]=263975,["quantity"]=1},{["kind"]="toyOwned",["itemId"]=263975}}},["after"]={"att-263975-669435f63a38:kystia"}},{["id"]="att-263975-669435f63a38:five-star-service",["kind"]="objective",["text"]="Work your assigned job: servers match steak, drink or cheese icons using the table on the right; the sweeper clears green floor messes; the dancer repeats the blue-circle sequence; the bouncer aims rowdy patrons toward the exit. Keep the rating at five stars until the game grants Five Star Review.",["sources"]={"https://github.com/ATTWoWAddon/AllTheThings/blob/52895ee664b61e08f091d514fe1556568d411570/db/Standard/Categories/Instances.lua","https://www.wowhead.com/achievement=62388","https://www.wowhead.com/item=263975","https://www.wowhead.com/npc=252458"},["recovery"]={["text"]="Recheck the current role controls and indicators if service stalls. A completed shift without the game’s five-star criterion is not this achievement. Restart the event only when its NPC permits."},["completeWhen"]={["any"]={{["kind"]="achievement",["achievementId"]=62388,["scope"]="account"},{["any"]={{["kind"]="itemCount",["itemId"]=263975,["quantity"]=1},{["kind"]="toyOwned",["itemId"]=263975}}}}},["manual"]=true,["after"]={"att-263975-669435f63a38:roles"}},{["id"]="att-263975-669435f63a38:reward",["kind"]="receive",["text"]="Check the awarded Feeling Fielder Mk. 7 and Toy Box ownership after Illicit Rain: Five Stars. The achievement can grant the toy directly; no final-boss kill is required.",["sources"]={"https://github.com/ATTWoWAddon/AllTheThings/blob/52895ee664b61e08f091d514fe1556568d411570/db/Standard/Categories/Instances.lua","https://www.wowhead.com/achievement=62388","https://www.wowhead.com/item=263975","https://www.wowhead.com/npc=252458"},["recovery"]={["text"]="Recheck the named room, selected difficulty and current game objectives. Continue advances only the guide cursor; it never records a kill, unlock, purchase or ownership."},["completeWhen"]={["any"]={{["any"]={{["kind"]="itemCount",["itemId"]=263975,["quantity"]=1},{["kind"]="toyOwned",["itemId"]=263975}}},{["any"]={{["kind"]="itemCount",["itemId"]=263975,["quantity"]=1},{["kind"]="toyOwned",["itemId"]=263975}}}}},["after"]={"att-263975-669435f63a38:five-star-service"}},{["id"]="att-26