emId"]=205419},["opportunityCompleteWhen"]={["kind"]="questTurnedIn",["questId"]=75352,["cadence"]="daily",["scope"]="character",["currentPeriodFlag"]=true}},["validation"]={["sourceChecked"]=true,["playtested"]=false,["automated"]=false,["reviewedAt"]="2026-10-24",["gaps"]={},["completePath"]=true},["coverageGaps"]={}},{["id"]="att-206565-5e29d982ab7f",["title"]="Collect Plagued Grain",["zone"]="Map 23 · NPC 206572",["expansion"]="Classic",["method"]="Instance",["cadence"]="once",["minutes"]=15,["rewards"]={206565},["requirements"]={},["destination"]={["mapID"]=23,["x"]=0.35700000000000004,["y"]=0.22899999999999998},["npcId"]=206572,["questIds"]={76390},["source"]="https://github.com/ATTWoWAddon/AllTheThings/blob/52895ee664b61e08f091d514fe1556568d411570/db/Standard/Categories/Instances.lua",["details"]="Structured route facts from the pinned ATT dataset. Check the offered quest, vendor stock or encounter in game; location and requirements are not a guarantee of a drop.",["metadataRoute"]=true,["costs"]={{"i",206576,15}},["facts"]={["awp"]=100105,["b"]=1,["category"]="Instances",["coords"]={["23"]={{35.7,22.9}},["115"]={{87.4,51.1}}},["cost"]={{"i",206576,15}},["description"]="1. Kill all bosses in Construct Quarter, and walk back to the entrance of The Halls of Reanimation.\010\0102. Walk up the slope to the platform on left side, and you should see two Grapple Point on two ledges to the left side. Grapple to the southern ledge.\010\0103. Speed-jump (Burning Rush/Speed potion) to the platform northeast of the ledge, and position yourself such that you are facing the corresponding platform to the northern ledge. Said platform is connected to a wall structure with two windows on the top. The left window ledge is the location of the next grappling point. Grapple up to it.\010\0104. Jump down to the brown ledge following the wall in a northeastern direction and around the corner, then over the skull on the wall, and back in a southeastern direction. The next grapple point is across the gap to a window ledge on left side, grapple to it.\010\0105. Follow the ledge in a southwestern direction and around the corner. You should see two pipe ends on the wall in front of you, the next grappling point on the left pipe. Grapple to it.\010\0106. Facing the position you grappled from, you should see Zackett Skullsmash on a window ledge. Jump down to the NPC.\010\0107. Use Stratholme Holy Water on Zackett Skullsmash and accept the quest Inconvenience Fee. You should have all required items on you and be able to turn it in immediately. This unlocks Zackett Skullsmash on an account-wide basis, and the Goblin will move to the central ring.\010\0108. You can safely get down by jumping down to the ledge above the entrance to the room, and leave through the Naxxramas Portal located where you killed Thaddius.\010\010",["expansionID"]=3,["headers"]={-75},["instanceID"]=754,["isRaid"]=1,["itemId"]=206565,["lineage"]={{["awp"]=30002,["coords"]={["23"]={{35.7,22.9}},["115"]={{87.4,51.1}}},["description"]="Make sure you go through 'Wards of the Dread Citadel' prior to farming this raid, then you will be able to obtain Scourgestones and special reagents during your grind. See the respective header for more information.",["instanceID"]=754,["isRaid"]=1,["kind"]="Instance",["mapID"]=162,["maps"]={163,164,165,166,167},["record"]=340719},{["kind"]="NPC",["npcID"]=206572,["record"]=341368,["sourceQuests"]={76390}},{["b"]=1,["cost"]={{"i",206576,15}},["itemID"]=206565,["kind"]="Toy",["record"]=341393}},["localFacts"]={["b"]=1,["cost"]={{"i",206576,15}},["itemID"]=206565,["kind"]="Toy",["record"]=341393},["mapID"]=162,["maps"]={163,164,165,166,167},["npcID"]=206572,["sourceQuests"]={76390}},["steps"]={{["id"]="att-206565-5e29d982ab7f:quest-76390",["kind"]="quest",["questId"]=76390,["destination"]={["mapID"]=23,["x"]=0.35700000000000004,["y"]=0.22899999999999998},["text"]="Check the next offered stage of quest #76390.",["completeWhen"]={["kind"]="questTurnedIn",