70/db/Standard/Categories/Instances.lua",["details"]="Structured route facts from the pinned ATT dataset. Check the offered quest, vendor stock or encounter in game; location and requirements are not a guarantee of a drop.",["metadataRoute"]=true,["costs"]={},["facts"]={["awp"]=70003,["b"]=1,["category"]="Instances",["coords"]={["75"]={{26.8,36.8}}},["description"]="This is a neutral Elite Creature that wanders the road.",["difficultyID"]=2,["expansionID"]=2,["headers"]={-75},["instanceID"]=251,["itemId"]=134019,["lineage"]={{["coords"]={["75"]={{26.8,36.8}}},["description"]="This is an event-triggered dungeon with the following steps:\010\0101. Talk to Erozion at the beginning of the dungeon to obtain a Pack of Incendiary Bombs.\010\0102. Traverse to the internment camps in Durnholde Keep and interact with a barrel in each building to start a fire and summon the first boss Lieutenant Drake.\010\0103. Find Thrall in the basement of the keep and follow him for the remainder of the dungeon.",["instanceID"]=251,["kind"]="Instance",["mapID"]=274,["record"]=338216},{["difficultyID"]=2,["kind"]="Difficulty",["record"]=338314},{["description"]="This is a neutral Elite Creature that wanders the road.",["kind"]="NPC",["npcID"]=28132,["record"]=338319},{["awp"]=70003,["b"]=1,["itemID"]=134019,["kind"]="Toy",["record"]=338320}},["localFacts"]={["awp"]=70003,["b"]=1,["itemID"]=134019,["kind"]="Toy",["record"]=338320},["mapID"]=274,["npcID"]=28132},["steps"]={{["id"]="att-134019-a8f9fd36a510:heroic-entry",["kind"]="travel",["text"]="Set Heroic dungeon difficulty yourself and enter Old Hillsbrad Foothills through the western timeway in Tanaris’s Caverns of Time. This is Escape from Durnholde, not the nearby Black Morass.",["sources"]={"https://github.com/ATTWoWAddon/AllTheThings/blob/52895ee664b61e08f091d514fe1556568d411570/db/Standard/Categories/Instances.lua","https://www.wowhead.com/item=134019","https://www.wowhead.com/npc=28132"},["recovery"]={["text"]="Recheck the named room, selected difficulty and current game objectives. Continue advances only the guide cursor; it never records a kill, unlock, purchase or ownership."},["destination"]={["mapID"]=75,["x"]=0.268,["y"]=0.368,["label"]="Old Hillsbrad timeway inside Caverns of Time",["interior"]=true,["directions"]="Descend through the main Caverns of Time tunnel and take the Old Hillsbrad timeway on the west side."},["manual"]=true,["completeWhen"]={["any"]={{["kind"]="itemCount",["itemId"]=134019,["quantity"]=1},{["kind"]="toyOwned",["itemId"]=134019}}}},{["id"]="att-134019-a8f9fd36a510:road-patrol",["kind"]="travel",["text"]="On entering Old Hillsbrad, ride straight out of the cave to the road. Find Don Carlos and his coyote between the river bridge and the Southshore signpost/tower. Do this before starting Thrall’s escort; no dungeon bosses are required for the hat.",["sources"]={"https://github.com/ATTWoWAddon/AllTheThings/blob/52895ee664b61e08f091d514fe1556568d411570/db/Standard/Categories/Instances.lua","https://www.wowhead.com/item=134019","https://www.wowhead.com/npc=28132"},["recovery"]={["text"]="The outdoor elderly Don Carlos is not the toy source. If you already advanced the escort and the patrol is absent, respect the saved Heroic run rather than following old reset exploits."},["manual"]=true,["completeWhen"]={["any"]={{["kind"]="itemCount",["itemId"]=134019,["quantity"]=1},{["kind"]="toyOwned",["itemId"]=134019}}},["after"]={"att-134019-a8f9fd36a510:heroic-entry"},["writtenDestination"]="Heroic Old Hillsbrad: leave the arrival cave straight ahead for the road. Search Don Carlos’s patrol between the river bridge and the Southshore signpost/tower before starting Thrall’s escort."},{["id"]="att-134019-a8f9fd36a510:loot",["kind"]="loot",["text"]="Pull Don Carlos away from neutral road patrols and defeat him and his coyote. Loot Don Carlos’s Famous Hat from the Heroic kill.",["sources"]={"https://github.com/ATTWoWAddon/AllTheThings/blob/52895ee664b61e08f091d514fe1556568d411570/db/Standard/Categories/Instances.lua","https://www.wowhead.com/item=134019","https://www.wowhead.com/npc=28132"},["recovery"]={["text"]="Normal’s quest hat is a different item. Check Heroic difficulty, corpse loot and bag space. Scatter Shot can interrupt combat; defeat or control the coyote and re-engage without pulling neutral patrols."},["completeWhen"]={["any"]={{["any"]={{["kind"]="itemCount",["itemId"]=134019,["quantity"]=1},{["kind"]="toyOwned",["itemId"]=134019}}},{["any"]={{["kind"]="itemCount",["itemId"]=134019,["quantity"]=1},{["kind"]="toyOwned",["itemId"]=134019}}}}},["after"]={"att-134019-a8f9fd36a510:road-patrol"},["writtenDestination"]="Heroic Old Hillsbrad: Don Carlos and his coyote patrol the road between the river bridge and the Southshore signpost/tower; loot his corpse after the fight."},{["id"]="att-134019-a8f9fd36a510:learn",["kind"]="learn",["text"]="Use Don Carlos’ Famous Hat from your bags to learn the toy.",["sources"]={"https://github.com/ATTWoWAddon/AllTheThings/blob/52895ee664b61e08f091d514fe1556568d411570/db/Standard/Categories/Instances.lua","https://www.wowhead.com/item=134019"},["recovery"]={["text"]="Only Toy Box ownership finishes this goal. Loot, mail, an achievement and the guide cursor remain separate evidence."},["completeWhen"]={["kind"]="toyOwned",["itemId"]=134019},["requires"]={["kind"]="itemCount",["itemId"]=134019,["quantity"]=1},["after"]={"att-134019-a8f9fd36a510:loot"}}},["outcome"]="random-drop",["currentPeriodFlag"]=false,["playStyle"]="group",["coverage"]="walkthrough",["walkthrough"]={["version"]=2,["contentVersion"]="2.4.0",["routeIds"]={"att-134019-a8f9fd36a510"},["includesPrerequisites"]=true,["completeWhen"]={["kind"]="toyOwned",["itemId"]=134019},["nodes"]={{["id"]="att-134019-a8f9fd36a510:heroic-entry",["kind"]="travel",["text"]="Set Heroic dungeon difficulty yourself and enter Old Hillsbrad Foothills through the western timeway in Tanaris’s Caverns of Time. This is Escape from Durnholde, not the nearby Bla