]={{["kind"]="itemCount",["itemId"]=17720,["quantity"]=1},{["kind"]="recipeLearned",["spellId"]=21940},{["kind"]="toyOwned",["itemId"]=17716}}},["after"]={"catalogue-craft-17716:profession"},["details"]={["destinationPolicy"]="Use an observed accessible Auction House or the faction service described here. Recipe tradability is supported by the cited full item tooltip. Stock and prices remain unknown until inspected."}},{["id"]="catalogue-craft-17716:recipe-use",["kind"]="use",["text"]="Use the physical recipe yourself after checking its displayed profession requirements. Wait for the actual learned-recipe observation; possessing or buying the recipe is a different state.",["sources"]={"https://raw.githubusercontent.com/ATTWoWAddon/AllTheThings/52895ee664b61e08f091d514fe1556568d411570/db/Standard/Categories/Craftables.lua","https://nether.wowhead.com/tooltip/spell/21940","https://nether.wowhead.com/tooltip/item/17720","https://warcraft.wiki.gg/wiki/Auctioneer_Jaxon","https://warcraft.wiki.gg/wiki/Auctioneer_Drezmit"},["recovery"]={["text"]="Refresh the actual profession, recipe and inventory. Continue or Skip moves the guide cursor only; it never creates learned recipes, materials or toy ownership."},["itemId"]=17720,["requires"]={["any"]={{["kind"]="itemCount",["itemId"]=17720,["quantity"]=1},{["kind"]="recipeLearned",["spellId"]=21940},{["kind"]="toyOwned",["itemId"]=17716}}},["completeWhen"]={["any"]={{["kind"]="recipeLearned",["spellId"]=21940},{["kind"]="toyOwned",["itemId"]=17716}}},["after"]={"catalogue-craft-17716:recipe-auction"}},{["id"]="catalogue-craft-17716:recipe-known",["kind"]="observe",["text"]="Confirm that this exact recipe is learned in the selected profession tier. A profession category or character level alone does not establish recipe access.",["sources"]={"https://raw.githubusercontent.com/ATTWoWAddon/AllTheThings/52895ee664b61e08f091d514fe1556568d411570/db/Standard/Categories/Craftables.lua","https://nether.wowhead.com/tooltip/spell/21940"},[