.com/ATTWoWAddon/AllTheThings/52895ee664b61e08f091d514fe1556568d411570/db/Standard/Categories/Craftables.lua","https://nether.wowhead.com/tooltip/spell/21940","https://warcraft.wiki.gg/wiki/Auctioneer_Jaxon","https://warcraft.wiki.gg/wiki/Auctioneer_Drezmit","https://nether.wowhead.com/tooltip/item/3860","https://nether.wowhead.com/tooltip/item/4389","https://nether.wowhead.com/tooltip/item/17202","https://nether.wowhead.com/tooltip/item/3829"},["recovery"]={["text"]="Refresh the actual profession, recipe and inventory. Continue or Skip moves the guide cursor only; it never creates learned recipes, materials or toy ownership."},["requires"]={["kind"]="recipeLearned",["spellId"]=21940},["completeWhen"]={["kind"]="evidenceUnavailable"},["manual"]=true,["interfaceObservation"]=true,["after"]={"catalogue-craft-17716:inspect-schematic"},["materials"]={{["itemId"]=3860,["quantity"]=8},{["itemId"]=4389,["quantity"]=4},{["itemId"]=17202,["quantity"]=4},{["itemId"]=3829,["quantity"]=1}},["details"]={["destinationPolicy"]="Tradable materials may be gathered or bought through chosen live Auction House listings. Bound materials must already be observed or use a separate authored source; they have no AH alternative.",["tradeEvidence"]={{["itemId"]=3860,["status"]="tradable-before-binding",["basis"]="Complete Retail item tooltip binding and quest-item classification; no bound/quest status",["sourceIds"]={"craft-source-00d85685bf09"},["name"]="Mithril Bar",["caveat"]="A route permits checking listings; stock and prices are never assumed. Actual game restrictions override metadata."},{["itemId"]=4389,["status"]="tradable-before-binding",["basis"]="Complete Retail item tooltip binding and quest-item classification; no bound/quest status",["sourceIds"]={"craft-source-7a5a2964a61e"},["name"]="Gyrochronatom",["caveat"]="A route permits checking listings; stock and prices are never assumed. Actual game restrictions override metadata."},{["itemId"]=17202,["status"]="tradable-before-bindi